def calculate_average(scores):
    """Calculate the average score of a list of scores."""
    return sum(scores) / len(scores)


def determine_grade(average_score):
    """Determine the grade based on the average score."""
    if average_score >= 90:
        return "A"
    elif average_score >= 80:
        return "B"
    elif average_score >= 70:
        return "C"
    elif average_score >= 60:
        return "D"
    else:
        return "F"


def calculate_grade(subject_scores):
    """Calculate the grade of a student based on their scores in three subjects."""
    scores = [score for score in subject_scores]
    average_score = calculate_average(scores)
    grade = determine_grade(average_score)
    return grade


